# RWDM_HIDE: Hide, Show, HideSwap: visibility without deleting. The script rwdm_hide_script.txt is generated by rwdm_gen.py. The oracle is exact set logic on four Point objects (ids 1..4 at x = 1..4):
# each step lists the objects that a SelAll (or the current selection) reaches, and the ids must equal the expected set exactly (and the count line must agree).
if [ -n "${DISPLAY:-}" ] && xset q >/dev/null 2>&1 || ! command -v xvfb-run >/dev/null 2>&1; then
  RWDM_HIDE_OUT="$(timeout 900 "$BIN" --smoke 60 --script "$HERE/rwdm_hide_script.txt" 2>&1)" || { echo "$RWDM_HIDE_OUT" | tail -40; echo "FAIL RWDM_HIDE_run: script exited non-zero"; fail=1; RWDM_HIDE_OUT=""; }
else
  RWDM_HIDE_OUT="$(timeout 900 xvfb-run -a -s "-screen 0 1600x900x24" "$BIN" --smoke 60 --script "$HERE/rwdm_hide_script.txt" 2>&1)" || { echo "$RWDM_HIDE_OUT" | tail -40; echo "FAIL RWDM_HIDE_run: script exited non-zero"; fail=1; RWDM_HIDE_OUT=""; }
fi
rwdm_hide_block() { awk -v name="$1" '$0 ~ ("Unknown command: RWDMBEGIN_" name "$") { on = 1; next } on && /Unknown command: RWDMBEGIN_/ { exit } on { print }' <<<"$RWDM_HIDE_OUT"; }
# rwdm_hide_ids STEP EXPECTED_IDS COUNT_LINE_OR_NONE DESC: the ids listed in the step, in order, are exactly EXPECTED_IDS ("-" = none); COUNT: the "N object(s) selected" line must say N
rwdm_hide_ids() {
  local blk got cnt; blk="$(rwdm_hide_block "$1")"
  got="$({ grep -oE '^history: Object [0-9]+ ' <<<"$blk" || true; } | sed -E 's/^history: Object ([0-9]+) /\1/' | tr '\n' ' ' | sed 's/ $//')"; [ -n "$got" ] || got="-"
  cnt="$({ grep -oE '^history: [0-9]+ object\(s\) selected' <<<"$blk" || true; } | tail -1 | sed -E 's/^history: ([0-9]+) .*/\1/')"
  if [ "$got" = "$2" ] && { [ "$3" = none ] || [ "$cnt" = "$3" ]; }; then echo "ok   RWDM_HIDE_$1: $4 (ids: $got)"
  else echo "FAIL RWDM_HIDE_$1: $4 (listed ids '$got', expected '$2'; selected-count line '${cnt:-none}', expected '$3')"; fail=1; fi
}
rwdm_hide_ids hide "3 4" 2 "after Hide of 1 and 2 a SelAll reaches only 3 and 4 (the hidden objects are concealed)"
rwdm_hide_ids hide_kept "1 2 3 4" 4 "Show brings the hidden 1 and 2 back unchanged: all four objects exist again with their ids, none was deleted"
rwdm_hide_ids swap_a "1 2" 2 "HideSwap with 1 and 2 hidden hides 3 and 4 and shows 1 and 2"
rwdm_hide_ids swap_b "3 4" 2 "a second HideSwap swaps back: 3 and 4 visible again"
rwdm_hide_ids show_all "1 2 3 4" 4 "Show reveals every hidden object: with all four hidden, Show leaves all four visible"
rwdm_hide_ids swap_none "-" 0 "HideSwap with nothing hidden hides everything: SelAll reaches no object"
